<template>
  <section class="writing-workspace">
    <header class="writing-heading"><div><h2>{{ l('技术标写作','Technical writing') }}</h2><span v-if="view.outlineRef">{{ l('已确认目录','Confirmed outline') }} V{{ view.outlineRef.version }}</span></div><div class="actions"><el-button type="primary" :disabled="!canDispatch || !selectedIds.length || busy" @click="dispatch(selectedIds)">{{ l('写作所选章节','Write selected chapters') }}<span v-if="selectedIds.length">（{{ selectedIds.length }}）</span></el-button><el-button type="primary" plain :disabled="!canAssemble || busy" @click="assemble">{{ l('组装技术标草稿','Assemble technical draft') }}</el-button></div></header>
    <el-alert v-if="!view.outlineRef" :title="l('目录尚未确认，不能开始章节写作。','Chapter writing is unavailable until the outline is confirmed.')" type="info" :closable="false" />
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <section v-if="view.manuscript" class="manuscript-summary" aria-labelledby="manuscript-title">
      <header><div><h3 id="manuscript-title">{{ l('已组装技术标草稿','Assembled technical draft') }}</h3><el-tag type="warning" effect="plain">{{ manuscriptStatus(view.manuscript.status) }}</el-tag><el-tag v-if="!manuscriptMatchesCurrent" type="danger" effect="plain">{{ l('需重新组装','Needs reassembly') }}</el-tag></div><span>V{{ view.manuscript.ref.version }} · {{ manuscriptChapters.length }}{{ l('章',' chapters') }}</span></header>
      <details v-for="(item,index) in manuscriptChapters" :key="item.chapterId" class="manuscript-chapter">
        <summary>{{ manuscriptChapterTitle(item,index) }}</summary>
        <div class="manuscript-body"><ChapterBlocks :blocks="manuscriptBlocks(item)" /></div>
      </details>
    </section>
    <div v-if="view.outlineRef && chapters.length" class="writing-layout">
      <nav class="chapter-nav" :aria-label="l('章节','Chapters')"><div class="tree-header"><h3>{{ l('章节','Chapters') }}</h3><el-checkbox :model-value="allSelected" :disabled="!canDispatch || busy" @change="toggleAll">{{ l('全选','Select all') }}</el-checkbox></div>
        <button v-for="chapter in chapters" :key="chapter.chapterId" type="button" class="chapter-link" :class="{active:activeChapterId===chapter.chapterId}" @click="activeChapterId=chapter.chapterId"><el-checkbox :model-value="selectedIds.includes(chapter.chapterId)" :disabled="!canDispatch || busy" @click.stop @change="toggleOne(chapter.chapterId,$event)" /><span class="chapter-title">{{ chapter.title }}</span><el-tag size="small" effect="plain">{{ chapterState(chapter) }}</el-tag></button>
      </nav>
      <article v-if="activeChapter" class="chapter-document">
        <header class="chapter-heading"><div><h3>{{ activeChapter.title }}</h3><el-tag effect="plain">{{ activeChapter.selected ? l('已选定','Selected') : l('尚未选定','Not selected') }}</el-tag></div><div class="actions"><el-button type="primary" plain :disabled="!canDispatch || busy || chapterBusy(activeChapter)" :loading="chapterBusy(activeChapter)" @click="dispatch([activeChapter.chapterId])">{{ l('写作本章','Write chapter') }}</el-button><el-button type="primary" plain :disabled="!activeChapter.selected || !activeChapter.editExpectedRef || !canWrite || busy" @click="openEditor()">{{ l('人工修订','Edit chapter') }}</el-button></div></header>
        <p v-if="activeChapter.tasks?.length" class="task-state">{{ l('本章任务','Chapter tasks') }} · {{ chapterState(activeChapter) }} <span v-if="latestTask(activeChapter)">· {{ l('尝试','Attempts') }} {{ latestTask(activeChapter)?.attemptCount }}</span></p>
        <div v-if="activeChapter.selected" class="selected-content"><section v-if="selectedEvidence(activeChapter.selected).missingMaterials.length || selectedEvidence(activeChapter.selected).unresolvedItems.length" class="selected-evidence" aria-label="Selected chapter evidence"><strong>{{ l('待补材料与确认','Materials and confirmations pending') }}</strong><details><summary>{{ l(`${selectedEvidence(activeChapter.selected).missingMaterials.length} 项材料 · ${selectedEvidence(activeChapter.selected).unresolvedItems.length} 项待确认`,`${selectedEvidence(activeChapter.selected).missingMaterials.length} materials · ${selectedEvidence(activeChapter.selected).unresolvedItems.length} confirmations`) }}</summary><ul v-if="selectedEvidence(activeChapter.selected).missingMaterials.length"><li v-for="(item,index) in selectedEvidence(activeChapter.selected).missingMaterials" :key="`material-${index}`">{{ item }}</li></ul><ul v-if="selectedEvidence(activeChapter.selected).unresolvedItems.length"><li v-for="(item,index) in selectedEvidence(activeChapter.selected).unresolvedItems" :key="`unresolved-${index}`">{{ item }}</li></ul></details></section><ChapterBlocks :blocks="blocks(activeChapter.selected)" /></div><el-empty v-else :description="l('尚无已选定正文','No selected chapter content yet')" />
        <section class="candidate-list"><h4>{{ l('写作候选','Writing candidates') }}</h4><p v-if="!activeChapter.candidates.length" class="empty-copy">{{ l('暂无写作候选','No writing candidates yet') }}</p><BiddingCandidateCompare v-for="candidate in activeChapter.candidates" :key="refKey(candidate.ref)" :candidate="candidate" :selected="sameRef(candidate.ref,activeChapter.selected?.ref)" :current-version="activeChapter.editExpectedRef?.version??0" :expected-version="expectedVersion(activeChapter,candidate)" :current-ref="activeChapter.editExpectedRef" :can-revise="canWrite && !!activeChapter.editExpectedRef" :busy="busy" @revise="openEditor(candidate)" @adopt="adopt(activeChapter,candidate)" /></section>
        <section v-if="failedTasks(activeChapter).length" class="retry-list"><h4>{{ l('需要重试的章节任务','Chapter tasks to retry') }}</h4><div v-for="task in failedTasks(activeChapter)" :key="task.taskId" class="retry-row"><el-tag type="danger" effect="plain">{{ taskStatus(task.status) }}</el-tag><span>{{ l('尝试','Attempts') }} {{ task.attemptCount }}</span><el-button type="primary" plain size="small" :disabled="busy || !canWrite" @click="$emit('retry-task',task.taskId)">{{ l('重试','Retry') }}</el-button></div></section>
      </article>
      <el-empty v-else :description="l('选择一个章节','Select a chapter')" />
    </div>
    <el-empty v-else-if="view.outlineRef" :description="l('已确认目录暂无章节','The confirmed outline has no chapters')" />
    <el-dialog v-model="editorOpen" :title="l('修订章节内容','Edit chapter blocks')" width="min(820px,94vw)" :close-on-click-modal="false"><el-form label-position="top"><div class="block-editor" data-testid="chapter-block-editor"><section v-for="(block,index) in draftBlocks" :key="index" class="editable-block" :data-block-editor-type="String(block.type||'unknown')"><header><strong>{{ blockLabel(String(block.type||'')) }}</strong><span v-if="block.type==='heading'">{{ l('级别','Level') }} {{ block.level }}</span></header><el-form-item v-if="block.type==='heading' || block.type==='paragraph'" :label="block.type==='heading'?l('标题文字','Heading text'):l('段落文字','Paragraph text')"><el-input :model-value="stringValue(block.text)" :type="block.type==='paragraph'?'textarea':'text'" :rows="3" :aria-label="block.type==='paragraph'?'Paragraph text':'Heading text'" maxlength="2000000" :disabled="busy" @update:model-value="setBlockText(index,'text',$event)" /></el-form-item><template v-else-if="block.type==='list'"><el-form-item v-for="(item,itemIndex) in listItems(block)" :key="itemIndex" :label="`${l('列表项','List item')} ${itemIndex+1}`"><el-input :model-value="listItemText(item)" :aria-label="`List item ${itemIndex+1}`" maxlength="2000000" :disabled="busy || !canEditListItem(item)" @update:model-value="setListItemText(index,itemIndex,$event)" /></el-form-item></template><template v-else-if="block.type==='table'"><el-form-item v-for="(column,columnIndex) in stringArray(block.columns)" :key="`column-${columnIndex}`" :label="`${l('列标题','Column')} ${columnIndex+1}`"><el-input :model-value="String(column)" :aria-label="`Table column ${columnIndex+1}`" :disabled="busy" @update:model-value="setTableColumn(index,columnIndex,$event)" /></el-form-item><div v-for="(row,rowIndex) in tableRows(block)" :key="`row-${rowIndex}`" class="table-row-edit"><strong>{{ l('第','Row ') }}{{ rowIndex+1 }}</strong><el-input v-for="(cell,cellIndex) in row" :key="cellIndex" :model-value="tableCellText(cell)" :aria-label="`Table row ${rowIndex+1} cell ${cellIndex+1}`" :disabled="busy || !canEditTableCell(cell)" @update:model-value="setTableCell(index,rowIndex,cellIndex,$event)" /></div></template><template v-else-if="block.type==='image'"><p class="preserved-block-note">{{ l('授权图片引用将原样保留。','The authorized image reference will be preserved.') }}</p><el-form-item v-if="typeof block.caption==='string'" :label="l('图片说明','Image caption')"><el-input :model-value="String(block.caption)" :disabled="busy" @update:model-value="setBlockText(index,'caption',$event)" /></el-form-item><el-form-item v-if="typeof block.alt==='string'" :label="l('替代文字','Alt text')"><el-input :model-value="String(block.alt)" :disabled="busy" @update:model-value="setBlockText(index,'alt',$event)" /></el-form-item></template><p v-else class="preserved-block-note">{{ l('此类内容保持原样。','This content block will be preserved unchanged.') }}</p></section><el-empty v-if="!draftBlocks.length" :description="l('当前候选没有可修订的内容块','This revision has no editable content blocks')" /></div></el-form><el-alert v-if="editError" :title="editError" type="error" :closable="false"/><template #footer><el-button @click="editorOpen=false">{{ l('取消','Cancel') }}</el-button><el-button type="primary" :loading="busy" :disabled="!canSaveEdit" @click="saveEdit">{{ l('保存修订','Save revision') }}</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import { computed, defineComponent, h, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import type { ChapterRevision, ManuscriptChapter, Ref, WritingChapter, WritingView } from '../api/types'
import BiddingCandidateCompare from './BiddingCandidateCompare.vue'
import { canAdopt } from '../shared/state'
const props=defineProps<{view:WritingView;canWrite:boolean;canDispatch:boolean;busy?:boolean;dispatchingChapterIds?:string[];error?:string;savedToken?:number;clearToken?:number}>()
const emit=defineEmits<{dispatch:[chapterIds:string[]];command:[body:{action:string;expected:Ref;payload:Record<string,unknown>}];'retry-task':[taskId:string];assemble:[refs:{chapterId:string;ref:Ref}[]]}>()
const {locale}=useI18n(),l=(zh:string,en:string)=>String(locale.value).startsWith('zh')?zh:en
const ChapterBlocks=defineComponent({props:{blocks:{type:Array,default:()=>[]}},setup(p){return()=>h('div',{class:'block-list'},(p.blocks as Record<string,unknown>[]).map((block,index)=>{const text=String(block.text||'');if(block.type==='heading')return h(`h${Math.min(6,Math.max(2,Number(block.level)||3))}`,{key:index},text);if(block.type==='list')return h(block.ordered?'ol':'ul',{key:index},(Array.isArray(block.items)?block.items:[]).map((item,i)=>h('li',{key:i},typeof item==='string'?item:item&&typeof item==='object'?String((item as Record<string,unknown>).text||(item as Record<string,unknown>).label||''):'') ));if(block.type==='table'){const columns=Array.isArray(block.columns)?block.columns:[],rows=Array.isArray(block.rows)?block.rows.filter(Array.isArray) as unknown[][]:[];const cell=(value:unknown)=>typeof value==='string'||typeof value==='number'?String(value):value&&typeof value==='object'&&typeof (value as Record<string,unknown>).text==='string'?String((value as Record<string,unknown>).text):'';return h('div',{key:index,class:'table-scroll'},[h('table',{class:'content-table'},[columns.length?h('thead',[h('tr',columns.map((column,columnIndex)=>h('th',{key:columnIndex,scope:'col'},cell(column))))]):null,h('tbody',rows.map((row,rowIndex)=>h('tr',{key:rowIndex},row.map((value,columnIndex)=>h('td',{key:columnIndex},cell(value))))))])])}if(block.type==='image')return h('figure',{key:index,class:'image-note'},[h('span',String(block.alt||'Image')),typeof block.caption==='string'?h('figcaption',block.caption):null]);return h('p',{key:index},text)}))}})
const chapters=computed(()=>props.view.chapters||[]),selectedIds=ref<string[]>([]),activeChapterId=ref(''),editorOpen=ref(false),draftBlocks=ref<Record<string,unknown>[]>([]),draftInitial=ref(''),editingPayload=ref<Record<string,unknown>>({}),editError=ref(''),editingRef=ref<Ref>(),editorDirty=computed(()=>JSON.stringify(draftBlocks.value)!==draftInitial.value)
const manuscriptChapters=computed<ManuscriptChapter[]>(()=>{const items=props.view.manuscript?.payload?.chapters;return Array.isArray(items)?items:[]})
const busy=computed(()=>!!props.busy),error=computed(()=>props.error||''),activeChapter=computed(()=>chapters.value.find(item=>item.chapterId===activeChapterId.value)),allSelected=computed(()=>chapters.value.length>0&&chapters.value.every(item=>selectedIds.value.includes(item.chapterId)))
const canSaveEdit=computed(()=>!!activeChapter.value?.editExpectedRef&&draftBlocks.value.length>0&&props.canWrite&&!busy.value)
const canAssemble=computed(()=>props.canWrite&&chapters.value.length>0&&chapters.value.every(item=>!!item.selected))
const manuscriptMatchesCurrent=computed(()=>{const manuscript=props.view.manuscript,refs=manuscript?.inputRefs;if(!manuscript||!Array.isArray(refs)||!props.view.outlineRef||manuscriptChapters.value.length!==chapters.value.length||refs.length!==manuscriptChapters.value.length+1||!sameRef(refs[0],props.view.outlineRef))return false;return manuscriptChapters.value.every((item,index)=>{const current=chapters.value.find(chapter=>chapter.chapterId===item.chapterId);return !!current?.selected&&sameRef(refs[index+1],current.selected.ref)})})
watch(chapters,items=>{if(!items.some(item=>item.chapterId===activeChapterId.value))activeChapterId.value=items[0]?.chapterId||'';selectedIds.value=selectedIds.value.filter(id=>items.some(item=>item.chapterId===id))},{immediate:true})
watch(()=>props.savedToken,()=>{if(props.savedToken){editorOpen.value=false;draftInitial.value=JSON.stringify(draftBlocks.value)}})
watch(()=>props.clearToken,()=>{if(props.clearToken){editorOpen.value=false;draftBlocks.value=[];draftInitial.value='';editingPayload.value={};editingRef.value=undefined;editError.value='';activeChapterId.value='';selectedIds.value=[]}})
function blocks(revision:ChapterRevision){const chapter=revision.payload.chapter as {blocks?:Record<string,unknown>[]} | undefined;return chapter?.blocks||[]}
function evidenceSummaries(value:unknown){if(!Array.isArray(value))return[];const fields=['title','text','description','reason','summary','item','material','requirement','issue','question','needed','nextStep','label'];return value.map(item=>{if(typeof item==='string')return item.trim();if(!item||typeof item!=='object'||Array.isArray(item))return'';const row=item as Record<string,unknown>;return fields.flatMap(key=>typeof row[key]==='string'&&row[key].trim()?[row[key].trim()]:[]).filter((text,index,all)=>all.indexOf(text)===index).join(' · ')||l('待补充事项','Details to be confirmed')}).filter(Boolean)}
function selectedEvidence(revision:ChapterRevision){const payload=revision.payload;return {missingMaterials:evidenceSummaries(payload.missingMaterials),unresolvedItems:evidenceSummaries(payload.unresolvedItems)}}
function refKey(value:Ref){return `${value.kind}:${value.id}:${value.version}:${value.digest}`}
function sameRef(left?:Ref,right?:Ref){return !!left&&!!right&&refKey(left)===refKey(right)}
function expectedVersion(_chapter:WritingChapter,candidate:ChapterRevision){return candidate.headGuard?.version??-1}
function sameServerRef(left?:Ref,right?:Ref){return !!left&&!!right&&left.kind===right.kind&&String(left.id)===String(right.id)&&left.digest===right.digest&&Number(left.version)===Number(right.version)}
function adoptable(chapter:WritingChapter,candidate:ChapterRevision){return !!chapter.editExpectedRef&&sameServerRef(chapter.editExpectedRef,candidate.headGuard)&&canAdopt(candidate.status,chapter.editExpectedRef.version,candidate.headGuard!.version)}
function taskStatus(value:string){return value==='QUEUED'?l('排队中','Queued'):value==='RUNNING'?l('执行中','Running'):value==='WAITING_RETRY'?l('等待重试','Waiting to retry'):value==='FAILED'?l('失败','Failed'):value==='CANCELLED'?l('已取消','Cancelled'):value==='STALE'?l('已失效','Outdated'):l('已完成','Succeeded')}
function latestTask(chapter:WritingChapter){return chapter.tasks?.[chapter.tasks.length-1]}
function failedTasks(chapter:WritingChapter){return (chapter.tasks||[]).filter(task=>['FAILED','CANCELLED','STALE'].includes(task.status))}
function chapterState(chapter:WritingChapter){const task=latestTask(chapter);if(task)return taskStatus(task.status);return chapter.selected?l('已有正文','Draft selected'):chapter.candidates.length?l('候选待选择','Candidate ready'):l('待写作','Not started')}
function manuscriptStatus(status:string){return status==='DRAFT_PENDING_REVIEW'?l('待审核','Pending review'):l('已组装','Assembled')}
function manuscriptChapterTitle(item:ManuscriptChapter,index:number){return chapters.value.find(chapter=>chapter.chapterId===item.chapterId)?.title||item.chapter?.title||l(`第${index+1}章`,`Chapter ${index+1}`)}
function manuscriptBlocks(item:ManuscriptChapter){return Array.isArray(item.chapter?.blocks)?item.chapter.blocks:[]}
function chapterBusy(chapter:WritingChapter){return (props.dispatchingChapterIds||[]).includes(chapter.chapterId)}
function toggleAll(value:boolean|string|number){selectedIds.value=value?chapters.value.map(item=>item.chapterId):[]}
function toggleOne(id:string,value:boolean|string|number){const next=new Set(selectedIds.value);if(value)next.add(id);else next.delete(id);selectedIds.value=[...next]}
function dispatch(ids:string[]){if(!props.canDispatch||!ids.length||busy.value)return;emit('dispatch',[...new Set(ids)])}
function blockLabel(type:string){return type==='heading'?l('标题','Heading'):type==='paragraph'?l('段落','Paragraph'):type==='list'?l('列表','List'):type==='table'?l('表格','Table'):type==='image'?l('图片','Image'):l('内容块','Content block')}
function stringValue(value:unknown){return typeof value==='string'?value:''}
function cloneBlockRows(value:unknown){return Array.isArray(value)?JSON.parse(JSON.stringify(value)) as Record<string,unknown>[]:[]}
function openEditor(candidate?:ChapterRevision){const chapter=activeChapter.value;if(!chapter)return;editingRef.value=chapter.editExpectedRef;const revision=candidate||chapter.selected;editingPayload.value=revision?.payload||{};draftBlocks.value=cloneBlockRows(blocks(revision||{payload:{}} as ChapterRevision));draftInitial.value=JSON.stringify(draftBlocks.value);editError.value='';editorOpen.value=true}
function listItems(block:Record<string,unknown>){return Array.isArray(block.items)?block.items:[]}
function listItemText(item:unknown){if(typeof item==='string')return item;if(item&&typeof item==='object'){const row=item as Record<string,unknown>;return stringValue(row.text??row.label??row.value)}return ''}
function canEditListItem(item:unknown){return typeof item==='string'||!!item&&typeof item==='object'&&['text','label','value'].some(key=>typeof (item as Record<string,unknown>)[key]==='string')}
function setBlockText(index:number,key:string,value:string){const block=draftBlocks.value[index];if(block)block[key]=value}
function setListItemText(index:number,itemIndex:number,value:string){const block=draftBlocks.value[index],items=block?.items;if(!Array.isArray(items))return;const item=items[itemIndex];if(typeof item==='string')items[itemIndex]=value;else if(item&&typeof item==='object'){const row=item as Record<string,unknown>,key=['text','label','value'].find(name=>typeof row[name]==='string');if(key)row[key]=value}}
function stringArray(value:unknown){return Array.isArray(value)?value.map(item=>typeof item==='string'?item:''):[]}
function tableRows(block:Record<string,unknown>){return Array.isArray(block.rows)?block.rows.filter(Array.isArray) as unknown[][]:[]}
function tableCellText(cell:unknown){if(typeof cell==='string'||typeof cell==='number')return String(cell);if(cell&&typeof cell==='object')return stringValue((cell as Record<string,unknown>).text);return ''}
function canEditTableCell(cell:unknown){return typeof cell==='string'||typeof cell==='number'||!!cell&&typeof cell==='object'&&typeof (cell as Record<string,unknown>).text==='string'}
function setTableColumn(index:number,columnIndex:number,value:string){const block=draftBlocks.value[index];if(Array.isArray(block?.columns))block.columns[columnIndex]=value}
function setTableCell(index:number,rowIndex:number,cellIndex:number,value:string){const rows=draftBlocks.value[index]?.rows;if(!Array.isArray(rows)||!Array.isArray(rows[rowIndex]))return;const row=rows[rowIndex] as unknown[],cell=row[cellIndex];if(typeof cell==='string'||typeof cell==='number')row[cellIndex]=value;else if(cell&&typeof cell==='object')(cell as Record<string,unknown>).text=value}
function saveEdit(){const chapter=activeChapter.value;if(!chapter||!editingRef.value||!canSaveEdit.value)return;const source=editingPayload.value;emit('command',{action:'EDIT_CHAPTER',expected:editingRef.value,payload:{chapterId:chapter.chapterId,blocks:draftBlocks.value,responses:Array.isArray(source.responses)?source.responses:[],citations:Array.isArray(source.citations)?source.citations:[],missingMaterials:Array.isArray(source.missingMaterials)?source.missingMaterials:[],unresolvedItems:Array.isArray(source.unresolvedItems)?source.unresolvedItems:[]}})}
function adopt(chapter:WritingChapter,candidate:ChapterRevision){if(!props.canWrite||!adoptable(chapter,candidate))return;emit('command',{action:'ADOPT_CHAPTER',expected:chapter.editExpectedRef!,payload:{chapterId:chapter.chapterId,candidateRef:candidate.ref}})}
function assemble(){if(!canAssemble.value)return;emit('assemble',chapters.value.map(item=>({chapterId:item.chapterId,ref:item.selected!.ref})))}
defineExpose({isDirty:()=>editorOpen.value&&editorDirty.value,clearSensitiveDraft:()=>{editorOpen.value=false;draftBlocks.value=[];draftInitial.value='';editingPayload.value={};editingRef.value=undefined;editError.value='';activeChapterId.value='';selectedIds.value=[]}})
</script>
<style scoped>
